word subscription.annual-renewable?(subscription: Subscription) -> Bool {
 effects none
 if equals(subscription.term(), "annual") { subscription.renewable() } else { false }
}
test subscription.annual-renewable?/yes {
 subscription::annual-renewable?(subscription::new("annual", true)) => true
}
test subscription.annual-renewable?/no {
 subscription::annual-renewable?(subscription::new("monthly", true)) => false
}
word customer.renewal-savings(customer: Customer, subscription: Subscription) -> Float {
 effects none
 float::subtract(customer.balance(), customer::renewal-balance(customer, subscription))
}
test customer.renewal-savings/basic {
 customer::renewal-savings(customer::new("premium", 100.0), subscription::new("annual", true)) => 14.5
}
